typedef void (*wuffs_private_impl__swizzle_ycc__convert_4_func)(
    wuffs_base__pixel_buffer* dst,
    uint32_t x,
    uint32_t x_end,
    uint32_t y,
    const uint8_t* up0,
    const uint8_t* up1,
    const uint8_t* up2,
    const uint8_t* up3);

static void  //
wuffs_private_impl__swizzle_ycca_bt601sr_src__convert_4_general(
    wuffs_base__pixel_buffer* dst,
    uint32_t x,
    uint32_t x_end,
    uint32_t y,
    const uint8_t* up0,
    const uint8_t* up1,
    const uint8_t* up2,
    const uint8_t* up3) {
  for (; x < x_end; x++) {
    uint32_t color =                                   //
        wuffs_base__color_ycc_bt601sr__as__color_u32(  //
            *up0++, *up1++, *up2++);
    color &= 0xFFFFFFu;
    color |= ((uint32_t)(*up3++)) << 24;
    wuffs_base__pixel_buffer__set_color_u32_argb_nonpremul_at(dst, x, y, color);
  }
}

static void  //
wuffs_private_impl__swizzle_ycca_bt601sr_src__convert_4_bgra_premul(
    wuffs_base__pixel_buffer* dst,
    uint32_t x,
    uint32_t x_end,
    uint32_t y,
    const uint8_t* up0,
    const uint8_t* up1,
    const uint8_t* up2,
    const uint8_t* up3) {
  size_t stride = dst->private_impl.planes[0].stride;
  uint8_t* row = dst->private_impl.planes[0].ptr + (stride * ((size_t)y));

  for (; x < x_end; x++) {
    uint32_t color =                                   //
        wuffs_base__color_ycc_bt601sr__as__color_u32(  //
            *up0++, *up1++, *up2++);
    color &= 0xFFFFFFu;
    color |= ((uint32_t)(*up3++)) << 24;

    uint8_t* ptr = row + (4 * ((size_t)x));
    uint32_t dst_color =
        wuffs_base__color_u32_argb_nonpremul__as__color_u32_argb_premul(color);
    wuffs_base__poke_u32le__no_bounds_check(ptr, dst_color);
  }
}

static void  //
wuffs_private_impl__swizzle_ycca_bt601sr_src_over__convert_4_general(
    wuffs_base__pixel_buffer* dst,
    uint32_t x,
    uint32_t x_end,
    uint32_t y,
    const uint8_t* up0,
    const uint8_t* up1,
    const uint8_t* up2,
    const uint8_t* up3) {
  for (; x < x_end; x++) {
    uint32_t color =                                   //
        wuffs_base__color_ycc_bt601sr__as__color_u32(  //
            *up0++, *up1++, *up2++);
    color &= 0xFFFFFFu;
    color |= ((uint32_t)(*up3++)) << 24;
    wuffs_base__pixel_buffer__composite_color_u32_nonpremul_at(dst, x, y,
                                                               color);
  }
}

static void  //
wuffs_private_impl__swizzle_ycca_bt601sr_src_over__convert_4_bgra_premul(
    wuffs_base__pixel_buffer* dst,
    uint32_t x,
    uint32_t x_end,
    uint32_t y,
    const uint8_t* up0,
    const uint8_t* up1,
    const uint8_t* up2,
    const uint8_t* up3) {
  size_t stride = dst->private_impl.planes[0].stride;
  uint8_t* row = dst->private_impl.planes[0].ptr + (stride * ((size_t)y));

  for (; x < x_end; x++) {
    uint32_t color =                                   //
        wuffs_base__color_ycc_bt601sr__as__color_u32(  //
            *up0++, *up1++, *up2++);
    color &= 0xFFFFFFu;
    color |= ((uint32_t)(*up3++)) << 24;

    uint8_t* ptr = row + (4 * ((size_t)x));
    uint32_t dst_color = wuffs_base__peek_u32le__no_bounds_check(ptr);
    dst_color = wuffs_private_impl__composite_premul_nonpremul_u32_axxx(
        dst_color, color);
    wuffs_base__poke_u32le__no_bounds_check(ptr, dst_color);
  }
}

static void  //
wuffs_private_impl__swizzle_cmyk__convert_4_general(
    wuffs_base__pixel_buffer* dst,
    uint32_t x,
    uint32_t x_end,
    uint32_t y,
    const uint8_t* up0,
    const uint8_t* up1,
    const uint8_t* up2,
    const uint8_t* up3) {
  for (; x < x_end; x++) {
    // It's called CMYK but, but for Adobe CMYK JPEG images in practice, it's
    // RGBW: 0xFFu means no ink instead of full ink. Note that a double
    // inversion is a no-op, so inversions might be implicit in the code below.
    uint32_t r = ((uint32_t)(*up0++));
    uint32_t g = ((uint32_t)(*up1++));
    uint32_t b = ((uint32_t)(*up2++));
    uint32_t w = ((uint32_t)(*up3++));
    r = ((r * w) + 0x7Fu) / 0xFFu;
    g = ((g * w) + 0x7Fu) / 0xFFu;
    b = ((b * w) + 0x7Fu) / 0xFFu;
    wuffs_base__pixel_buffer__set_color_u32_argb_premul_at(
        dst, x, y, 0xFF000000u | (r << 16u) | (g << 8u) | (b << 0u));
  }
}

static void  //
wuffs_private_impl__swizzle_ycck__convert_4_general(
    wuffs_base__pixel_buffer* dst,
    uint32_t x,
    uint32_t x_end,
    uint32_t y,
    const uint8_t* up0,
    const uint8_t* up1,
    const uint8_t* up2,
    const uint8_t* up3) {
  for (; x < x_end; x++) {
    // We invert once again: 0xFFu means no ink instead of full ink.
    uint32_t color =                                   //
        wuffs_base__color_ycc_bt601fr__as__color_u32(  //
            *up0++, *up1++, *up2++);
    uint32_t r = 0xFFu - (0xFFu & (color >> 16u));
    uint32_t g = 0xFFu - (0xFFu & (color >> 8u));
    uint32_t b = 0xFFu - (0xFFu & (color >> 0u));
    uint32_t w = ((uint32_t)(*up3++));
    r = ((r * w) + 0x7Fu) / 0xFFu;
    g = ((g * w) + 0x7Fu) / 0xFFu;
    b = ((b * w) + 0x7Fu) / 0xFFu;
    wuffs_base__pixel_buffer__set_color_u32_argb_premul_at(
        dst, x, y, 0xFF000000u | (r << 16u) | (g << 8u) | (b << 0u));
  }
}

